/*
 * Minimal local markdown renderer stub.
 *
 * Plugin Repo rules disallow loading third-party JS from CDNs.
 * This file provides a very small `marked.parse()` compatible API so
 * the admin UI continues to work without external dependencies.
 *
 * NOTE: This is NOT a full Markdown implementation.
 */
(function(){
  function esc(s){
    return String(s||'').replace(/[&<>"']/g,function(m){
      return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]);
    });
  }

  function basic(md){
    md = String(md||'');
    // Very small subset: headers + code blocks + paragraphs.
    var lines = md.split(/\r?\n/);
    var out = [];
    var inCode = false;
    var code = [];
    lines.forEach(function(line){
      if(line.trim().startsWith('```')){
        if(!inCode){ inCode = true; code = []; }
        else {
          inCode = false;
          out.push('<pre class="pf-pre"><code>' + esc(code.join('\n')) + '</code></pre>');
        }
        return;
      }
      if(inCode){ code.push(line); return; }
      if(/^###\s+/.test(line)) { out.push('<h3>' + esc(line.replace(/^###\s+/,'')) + '</h3>'); return; }
      if(/^##\s+/.test(line))  { out.push('<h2>' + esc(line.replace(/^##\s+/,'')) + '</h2>'); return; }
      if(/^#\s+/.test(line))   { out.push('<h1>' + esc(line.replace(/^#\s+/,'')) + '</h1>'); return; }
      if(line.trim() === '') { out.push(''); return; }
      out.push('<p>' + esc(line) + '</p>');
    });
    if(inCode){ out.push('<pre class="pf-pre"><code>' + esc(code.join('\n')) + '</code></pre>'); }
    return out.join('\n');
  }

  window.marked = window.marked || {};
  window.marked.parse = window.marked.parse || basic;
})();

